class Solution {
public:
    vector<int> smallestMissingValueSubtree(vector<int>& parents, vector<int>& nums) {
        int n = parents.size();
        vector<vector<int>> children(n);
        for (int i = 1; i < n; i++) {
            children[parents[i]].push_back(i);
        }

        vector<int> ans(n, 1);

        int oneNode = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) { oneNode = i; break; }
        }

        if (oneNode == -1) return ans;

        vector<bool> seen(n + 2, false);
        vector<bool> visited(n, false);
        int missing = 1;

        int cur = oneNode;
        while (cur != -1) {
            stack<int> st;
            st.push(cur);
            while (!st.empty()) {
                int u = st.top(); st.pop();
                if (visited[u]) continue;
                visited[u] = true;
                if (nums[u] <= n + 1) seen[nums[u]] = true;
                for (int c : children[u]) {
                    if (!visited[c]) st.push(c);
                }
            }
            while (missing <= n + 1 && seen[missing]) missing++;
            ans[cur] = missing;
            cur = parents[cur];
        }

        return ans;
    }
};
